import { containsHtml, textInputError } from "../shared/inputValidation.cjs";
import { safeMemberNotificationHref } from "../shared/memberNotificationTarget.cjs";

export function plainTextMessage(value: string, max: number, multiline = false): string {
  if (containsHtml(value)) return "HTML tidak diperbolehkan pada kolom ini.";
  return textInputError(value, { max, multiline, required: false }) ?? "";
}

// Notification destinations are generated by the circulation service. Only
// those existing local routes may be used for navigation, including new tabs.
export function notificationDestination(value: unknown): string | null {
  return safeMemberNotificationHref(value);
}
